import {fields} from './fields.mjs';
import {traits} from './traits.mjs';
import {initialState,clone,isDirty,validate,saveReport,routeState,previewBatch,applyBatch,sectionNames,traitAverage,groupAverage,previewChanges,applyChanges,reportingSeniorKeys,paygrades,validateSenior,validateRSCA,psgRSCA,captureComparison} from './model.mjs';
const key='swift-navfit-design-prototype-v2';
let bulkValues={},bulkTouched=new Set(),bulkSection=0,comparisonDraft={},comparisonBatchGuard=null;
let state;try{state=JSON.parse(localStorage.getItem(key))||initialState();}catch{state=initialState();}
state.reportingSeniors??=[];
let seniorDraft=null,seniorErrors={},seniorBaseline={};
let page='overview',editor=null,section=0,errors={},selected=new Set(),batch=[],groupTab='Members',listScroll=0;
const filters={search:'',kind:'All',status:'All',folder:'All',archive:'Active'};
const main=document.querySelector('#main'),dialog=document.querySelector('#dialog');
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const persist=()=>{try{localStorage.setItem(key,JSON.stringify(state));}catch{notify('Browser storage is unavailable. Changes last only for this prototype session.');}};
const report=id=>state.reports.find(r=>r.id===Number(id));
const button=(text,action,cls='',attrs='')=>`<button class="${cls}" data-action="${action}" ${attrs}>${text}</button>`;
const badge=(text,cls='')=>`<span class="badge ${cls}">${esc(text)}</span>`;
function statusBadge(r){const s=routeState(state,r);return badge(s,s==='Local approval'?'green':s.includes('restart')?'amber':s==='In review'?'blue':'');}
function notify(text){const n=document.querySelector('#notice');n.textContent=text;n.style.display='block';clearTimeout(notify.timer);notify.timer=setTimeout(()=>n.style.display='none',4500);}
function modal(title,body,actions){dialog.innerHTML=`<h2 id="dialog-title">${esc(title)}</h2>${body}<div class="actions">${actions}</div>`;dialog.showModal();}
function nav(){const items=[['overview','Overview'],['reports','Reports'],['groups','Summary groups'],['work','My Work'],['resources','Resources'],['settings','Settings & Help']];document.querySelector('#navigation').innerHTML='<div class="nav-caption">Workspace</div>'+items.map(([id,label])=>`<a href="#${id}" ${page===id||page==='editor'&&id==='reports'||page==='group-detail'&&id==='groups'||['seniors','senior-editor'].includes(page)&&id==='resources'?'aria-current="page"':''}>${label}</a>`).join('');document.querySelector('#profile').textContent='Contributor: '+state.profile;}
function heading(title,description,actions=''){return `<div class="page-heading"><div><h1>${title}</h1><p class="muted">${description}</p></div><div class="actions">${actions}</div></div>`;}
function requestNavigation(target){if(page==='senior-editor'&&(seniorIsDirty()||Object.keys(seniorBaseline).length)){modal('Keep reporting senior changes?','<p>You have unsaved record or RSCA entries. Save the record and any completed baseline, discard changes, or keep editing.</p>',button('Keep editing','cancel')+button('Discard changes','senior-leave-discard')+button('Save and leave','senior-leave-save','primary'));dialog.dataset.destination=target;return;}if(editor&&isDirty(report(editor.id).values,editor.values)){modal('Keep your report changes?', '<p>You have unsaved changes. Saving creates a report revision; automatic recovery is separate.</p>',button('Keep editing','cancel')+button('Discard changes','leave-discard','danger')+button('Save and leave','leave-save','primary'));dialog.dataset.destination=target;return;}navigate(target);}
function navigate(target){editor=null;errors={};page=target;location.hash=target;render();window.scrollTo(0,0);main.focus();}
function render(){nav();const views={overview:overview,reports:reports,groups:groups,'group-detail':groupDetail,'bulk-editor':bulkEditor,work:myWork,resources,settings,editor:renderEditor,bulk:bulk,import:importView,seniors:seniorList,'senior-editor':seniorEditor};main.innerHTML=(views[page]||overview)();if(page==='editor')bindFields();if(page==='bulk-editor')bindBulkFields();if(page==='senior-editor')bindSeniorFields();if(page==='reports')window.scrollTo(0,listScroll);}
function reportRows(rows,selectable=true){return `<div class="table-wrap"><table><thead><tr>${selectable?'<th><span class="small">Select</span></th>':''}<th>Member</th><th>Report</th><th>Period ending</th><th>Status</th><th>Folder</th><th></th></tr></thead><tbody>${rows.map(r=>`<tr>${selectable?`<td><input type="checkbox" aria-label="Select ${esc(r.values.MemberName)}" data-select="${r.id}" ${selected.has(r.id)?'checked':''}></td>`:''}<td><button class="link" data-action="open" data-id="${r.id}">${esc(r.values.MemberName||'Unnamed member')}</button><div class="hint">${esc(r.values.RankRate)}</div></td><td>${esc(r.values.FormKind)}</td><td>${esc(r.values.PeriodEnd||'Not entered')}</td><td>${statusBadge(r)}</td><td>${esc(r.folder||'Unfiled')}</td><td>${button('Open','open','','data-id="'+r.id+'"')}</td></tr>`).join('')}</tbody></table></div>`;}
function overview(){return heading('Overview','Your reports, groups and review tasks in one local workspace.',button('New report','new','primary')+button('New group','new-group'))+`<div class="cards"><div class="card"><h2>Reports</h2><span class="metric">${state.reports.filter(r=>!r.archived).length}</span><p class="muted">Active reports in this workspace</p>${button('Go to reports','goto-reports')}</div><div class="card"><h2>Summary groups</h2><span class="metric">${state.groups.length}</span><p class="muted">Explicit groups, separate from folders</p>${button('Open groups','goto-groups')}</div><div class="card"><h2>My Work</h2><span class="metric">${state.routes.filter(r=>r.steps.some(s=>s.name===state.profile&&s.state==='Pending')).length}</span><p class="muted">Assigned review steps</p>${button('Review my tasks','goto-work')}</div></div><br>${state.recovery?`<div class="alert"><strong>Pending edits are available to recover.</strong><p>Jamie Taylor has an automatic recovery checkpoint. It is not a saved revision.</p>${button('Review recovery','recovery')}</div>`:''}<section class="card"><h2>Recent reports</h2>${reportRows(state.reports.filter(r=>!r.archived).slice(0,3),false)}</section>`;}
function optionFilter(label,name,values,value){return `<label>${label}<select data-filter="${name}">${values.map(v=>`<option ${v===value?'selected':''}>${esc(v)}</option>`).join('')}</select></label>`;}
function filteredReports(){return state.reports.filter(r=>(filters.archive==='All'||r.archived===(filters.archive==='Archived'))&&(filters.kind==='All'||r.values.FormKind===filters.kind)&&(filters.folder==='All'||r.folder===filters.folder)&&(filters.status==='All'||routeState(state,r)===filters.status)&&(!filters.search||[r.values.MemberName,r.values.Title,r.values.RankRate].join(' ').toLowerCase().includes(filters.search.toLowerCase())));}
function reports(){const rows=filteredReports();return heading('Reports','Find a report, resume drafting or work with a selected set.',button('New report','new','primary')+button('Import','goto-import'))+`<section class="card"><div class="toolbar"><label class="search">Search reports<input type="search" data-filter="search" value="${esc(filters.search)}" placeholder="Member, grade/rate or draft title"></label>${optionFilter('Report type','kind',['All','EVAL','CHIEFEVAL','FITREP'],filters.kind)}${optionFilter('Status','status',['All','Draft','In review','Review needs restart','Local approval','Returned'],filters.status)}${optionFilter('Folder','folder',['All',...new Set(state.reports.map(r=>r.folder))],filters.folder)}${optionFilter('Show','archive',['Active','Archived','All'],filters.archive)}</div><div class="actions" style="margin-bottom:16px">${badge(selected.size+' selected')}${button('Bulk change','bulk-start','',selected.size?'':'disabled title="Select one or more editable reports first"')}${button('Move to folder','move','',selected.size?'':'disabled')}${button('Archive / recover','archive','',selected.size?'':'disabled')}${button('Clear filters','clear-filters','quiet')}</div>${rows.length?reportRows(rows):'<div class="empty"><h2>No matching reports</h2><p class="muted">Try a different search or clear your filters.</p>'+button('Clear filters','clear-filters')+'</div>'}<p class="hint">${rows.length} reports shown. Folders organize reports; they do not define summary groups.</p></section>`;}
function openEditor(id){listScroll=window.scrollY;const r=report(id),gs=state.groups.filter(g=>g.members.includes(r.id));editor={id:r.id,values:clone(r.values),groupId:gs.length===1?gs[0].id:null};errors={};section=0;page='editor';location.hash='editor';render();window.scrollTo(0,0);main.focus();}
function sectionRange(i,kind){const ranges=['Blocks 1â€“21','Blocks 22â€“27','Blocks 28â€“29','Blocks 30â€“32','Blocks 33â€“39',kind==='EVAL'?'Includes comments block 43':kind==='CHIEFEVAL'?'Includes comments block 40':'Includes comments block 41','Contact, raters and statement','Local workspace only','Saved revisions only','Saved revisions only'];return ranges[i];}
function renderEditor(){const r=report(editor.id),locked=r.archived||r.state==='Approved';return `<div class="breadcrumbs"><a href="#reports">Reports</a> / ${esc(r.values.MemberName||'New report')}</div><div class="editor-header"><div class="page-heading" style="margin:0"><div><h1>${esc(editor.values.MemberName||'New report')}</h1><div class="muted">${esc(r.values.FormKind)} Â· ${esc(editor.values.RankRate||'Grade/rate not entered')} Â· ${esc(editor.values.PeriodStart||'Start date')} â€“ ${esc(editor.values.PeriodEnd||'End date')}</div></div><div class="actions">${statusBadge(r)}${button('More actions','report-more')}</div></div><div class="report-meta"><span id="dirty-indicator">${isDirty(r.values,editor.values)?badge('Unsaved changes','amber'):badge('Saved revision '+r.revision,'green')}</span><span id="checkpoint-status" class="hint">${state.recovery?.reportId===r.id?'Recovery checkpoint available':'Automatic recovery every 30 seconds'}</span></div><div id="average-summary">${averageSummary(r)}</div></div>${locked?`<div class="alert info"><strong>${r.archived?'Archived report':'Local approval â€” editing locked'}</strong><p>You can read sections and history. ${r.archived?'Recover this report to edit it.':'Reopen with a reason to make changes. Local approval is not an official signature.'}</p>${button(r.archived?'Recover report':'Reopen report','reopen')}</div>`:''}<div class="editor-layout"><nav class="section-nav" aria-label="Report sections">${sectionNames.map((name,i)=>i===1?'':`${i===7?'<div class="local-label">Local workspace</div>':''}<button data-action="section" data-section="${i}" ${section===i?'aria-current="page"':''}>${name}<small>${sectionRange(i,r.values.FormKind)}</small></button>`).join('')}</nav><section class="card" id="section-content">${editorSection(r,locked)}</section></div><div class="save-bar"><span class="status" id="save-status">${isDirty(r.values,editor.values)?'Your changes have not been saved.':'Saved revision '+r.revision+' Â· '+esc(r.history[0].at)}</span>${button('Back to reports','goto-reports')}${button('Save draft','save','primary',locked?'disabled title="Reopen the report before saving changes"':'')}</div>`;}
function fieldHTML(f,locked,values=editor.values){let block=f.blocks?.[values.FormKind]??f.block;if(f.key==='OfficialComments')block=values.FormKind==='EVAL'?'43':values.FormKind==='CHIEFEVAL'?'40':'41';if(f.key==='Designator')block='3';const v=values[f.key]??'',error=errors[f.key],trait=traits.find(t=>t.FormKind===values.FormKind&&'Trait'+t.Block===f.key),label=trait?trait.Title.replace(/\s+/g,' ').trim():f.key==='RankRate'&&values.FormKind==='CHIEFEVAL'?'Rating':f.label;const unavailable=f.forms&&!f.forms.includes(values.FormKind);locked=locked||unavailable;const attrs=`id="field-${f.key}" data-field="${f.key}" ${locked?'disabled':''} ${error?'aria-invalid="true"':''} aria-describedby="hint-${f.key}${error?' error-'+f.key:''}"`;let control;if(f.checkbox)control=`<label class="check-row check-field"><input type="checkbox" ${attrs} ${v===(f.key==='ObservationStatus'?'NOB':'Yes')?'checked':''}>${esc(label)}</label>`;else if(f.options)control=`<select ${attrs}>${f.options.map(o=>`<option value="${esc(o)}" ${v===o?'selected':''}>${o?esc(o):'Not entered'}</option>`).join('')}</select>`;else if(f.multiline)control=`<textarea ${attrs} rows="${f.key==='OfficialComments'?10:5}">${esc(v)}</textarea>`;else control=`<input ${attrs} value="${esc(f.digits===9&&/^\d{9}$/.test(v)?v.slice(0,3)+'-'+v.slice(3,5)+'-'+v.slice(5):v)}" ${f.digits?'inputmode="numeric"':''} ${f.date?'placeholder="YYYY-MM-DD"':''}>`;return `<div class="field ${f.multiline?'wide':''}"><label for="field-${f.key}">${f.checkbox?'':esc(label)}${block?`<span class="block">Block ${esc(block)}</span>`:''}</label>${control}<div id="hint-${f.key}" class="field-note">${unavailable?'Not applicable to this report form; existing values are retained. ':''}${f.checkbox&&!v?'Not entered. ':''}${f.date?'YYYY-MM-DD. ':''}${f.limit?'Up to '+f.limit+' characters. ':''}${f.key==='OfficialComments'?'<span id="narrative-count">'+v.length+'</span> characters Â· Printed fit is not verified.':f.key==='OfficialName'?'Stored separately from name parts below; no automatic overwrite.':f.key==='Designator'&&values.FormKind!=='FITREP'?'Existing designation field; additional native qualifications mapping is pending.':''}</div>${error?`<span class="field-error" id="error-${f.key}">${esc(error)}</span>`:''}</div>`;}
function errorSummary(){const entries=Object.entries(errors);return entries.length?`<div class="alert error" role="alert"><h3>Review ${entries.length} ${entries.length===1?'entry':'entries'} before saving</h3><ul>${entries.map(([key,message])=>`<li><a href="#field-${key}" data-error-field="${key}">${esc(fields.find(f=>f.key===key).label)}: ${esc(message)}</a></li>`).join('')}</ul><span class="hint">Incomplete drafts can be saved. These entries have invalid formats or exceed supported lengths.</span></div>`:'';}
function editorSection(r,locked){if(section===8)return reviewSection(r);if(section===9)return historySection(r);const fs=fields.filter(f=>f.section===section&&f.key!=='FormKind'&&!f.legacyHidden).sort((a,b)=>(parseInt(a.blocks?.[r.values.FormKind]??a.block)||999)-(parseInt(b.blocks?.[r.values.FormKind]??b.block)||999));return `<h2>${sectionNames[section]}</h2><p class="hint">${sectionRange(section,r.values.FormKind)}${section===7?' Â· Not part of the official report.':''}</p>${errorSummary()}${section===0?seniorSelector():''}${section===4?'<div class="alert info">Select a trait mark to read its guidance. Blank and NOB are different. Arithmetic excludes both.</div>':''}<div class="field-grid">${section===0?memberFields(fs,locked):fs.map(f=>fieldHTML(f,locked)).join('')}</div>${section===4?'<div class="card" style="margin-top:20px;background:#f7f9fb"><h3>Trait guidance</h3><p id="trait-guidance" class="muted">Focus a trait to view the guidance pattern. The Access implementation will use the existing form-specific reference catalogue.</p></div>':''}${section===5?'<div class="actions" style="margin-top:16px">'+button('Insert narrative snippet','snippet','',''+(locked?'disabled':''))+'</div>':''}`;}
function reviewSection(r){const route=state.routes.find(x=>x.reportId===r.id),stale=route&&route.revision!==r.revision;return `<h2>Review</h2><p class="muted">Review comments and decisions are linked to saved report revisions. Pending editor changes are separate.</p>${stale?'<div class="alert"><strong>This review is stale.</strong><p>The report changed after routing. Start a new route for the latest saved revision.</p></div>':''}<div class="actions">${button(route?'Restart review':'Start review','start-review','primary')}${button('Run draft checks','checks')}${route&&route.steps.every(s=>s.state==='Accepted')&&!stale?button('Record local approval','approve'):''}</div><h3 style="margin-top:24px">Reviewer route ${route?'Â· saved revision '+route.revision:''}</h3>${route?route.steps.map((s,i)=>`<div class="route-step"><span class="route-number">${i+1}</span><div class="who"><strong>${esc(s.name)}</strong><div class="hint">Local contributor</div></div>${badge(s.state,s.state==='Pending'?'blue':'')}</div>`).join(''):'<p class="muted">No reviewer route has been started.</p>'}<div class="actions">${route&&!stale?button('Accept review step','accept')+button('Return with feedback','return'):''}</div><h3 style="margin-top:26px">Review comments</h3>${r.comments.map(c=>`<div class="history-row"><strong>${esc(c.author)} Â· revision ${c.revision}</strong><p>${esc(c.text)}</p>${badge(c.resolved?'Resolved':'Open')}${button(c.resolved?'Reopen':'Resolve','resolve-comment','','data-index="'+r.comments.indexOf(c)+'"')}</div>`).join('')||'<p class="muted">No review comments yet.</p>'}<label style="margin-top:12px">Comment on saved revision ${r.revision}<textarea id="review-comment" rows="3" placeholder="Add a clear suggestion or question"></textarea></label><div class="actions" style="margin-top:10px">${button('Post comment','post-comment')}</div>`;}
function historySection(r){return `<h2>History</h2><p class="muted">Saved revisions are retained. Restoring creates a new revision.</p>${r.history.map(h=>`<div class="history-row"><strong>Revision ${h.revision} Â· ${esc(h.reason)}</strong><span class="hint">${esc(h.at)}</span><div class="actions" style="margin-top:10px">${button('Compare','compare','','data-revision="'+h.revision+'"')}${button('Restore as new revision','restore-revision','','data-revision="'+h.revision+'" '+(h.revision===r.revision||r.state==='Approved'||r.archived?'disabled':''))}</div></div>`).join('')}`;}
function bindFields(){main.querySelectorAll('[data-field]').forEach(input=>{if(input.type==='checkbox')input.indeterminate=!editor.values[input.dataset.field];input.addEventListener('input',()=>{editor.values[input.dataset.field]=input.type==='checkbox'?(input.dataset.field==='ObservationStatus'?(input.checked?'NOB':'Observed'):(input.checked?'Yes':'No')):(fields.find(f=>f.key===input.dataset.field)?.digits===9&&/^\d{3}-\d{2}-\d{4}$/.test(input.value)?input.value.replaceAll('-',''):input.value);updateDirty();if(input.dataset.field==='OfficialComments')document.querySelector('#narrative-count').textContent=input.value.length;});input.addEventListener('blur',()=>{const e=validate(editor.values)[input.dataset.field];input.setAttribute('aria-invalid',e?'true':'false');});if(input.dataset.field.startsWith('Trait'))input.addEventListener('focus',()=>{const trait=traits.find(t=>t.FormKind===editor.values.FormKind&&'Trait'+t.Block===input.dataset.field);document.querySelector('#trait-guidance').textContent=trait?(trait.Marks[input.value]||trait.GeneralDescription||'No reference text for this selection.'):'No catalogue entry available.';});});}
function updateDirty(){const avg=document.querySelector('#average-summary');if(avg)avg.innerHTML=averageSummary(report(editor.id));const dirty=isDirty(report(editor.id).values,editor.values);document.querySelector('#dirty-indicator').innerHTML=badge(dirty?'Unsaved changes':'Saved revision '+report(editor.id).revision,dirty?'amber':'green');document.querySelector('#save-status').textContent=dirty?'Your changes have not been saved.':'No pending changes.';}
function save(){const result=saveReport(state,editor.id,editor.values);if(result.errors){errors=result.errors;section=fields.find(f=>f.key===Object.keys(errors)[0]).section;render();document.querySelector('[aria-invalid=true]')?.focus();return false;}errors={};persist();render();notify(result.changed?'Draft saved as revision '+report(editor.id).revision+'.':'No changes to save.');return true;}
function groupDetail(){const g=state.groups[0];return heading('Summary groups','Explicit rosters and shared work, independent of organizational folders.',button('Back to groups','goto-groups'))+(!g?'<div class="card empty"><h2>No groups yet</h2><p>Create a group and choose its members.</p></div>':`<section class="card"><div class="page-heading"><div><h2>${esc(g.title)}</h2><p class="muted">${g.grade} Â· ${g.kind} Â· ${g.members.length} members ${badge('Local draft group')}</p></div>${button('Choose group','choose-group')}</div><div class="tabs" role="tablist">${['Members','Shared defaults','Review','Comparison','History'].map(t=>`<button role="tab" data-action="group-tab" data-tab="${t}" aria-selected="${groupTab===t}">${t}</button>`).join('')}</div>${groupRSCA(g)}${groupContent(g)}</section>`);}
function groupContent(g){if(groupTab==='Members')return `<div class="actions" style="margin-bottom:16px">${button('Add members','add-members','primary')}${button('Bulk change members','group-bulk')}</div>${reportRows(g.members.map(report),false)}<div class="alert info" style="margin-top:20px">Membership is explicitly selected. Full Navy eligibility checks are still under development. Exceptions require deliberate review.</div>`;if(groupTab==='Shared defaults')return `<h3>Suggested ship / station</h3><p class="muted">Defaults are suggestions. Changes never silently overwrite report values.</p><label>Group default<input id="group-default" value="${esc(g.defaults.ShipStation||'')}"></label><div class="actions" style="margin-top:16px">${button('Save default suggestion','save-default','primary')}${button('Preview applying to members','default-preview')}</div>`;if(groupTab==='Review')return `<h3>Saved-report review status</h3>${reportRows(g.members.map(report),false)}<p class="hint">Open a reportâ€™s Review section to manage its route. Contributor profiles provide attribution, not authentication.</p>`;if(groupTab==='Comparison')return comparisonContent(g);return g.history.map(t=>`<div class="history-row">${esc(t)}</div>`).join('');}
function myWork(){const tasks=state.routes.filter(t=>t.steps.some(s=>s.name===state.profile&&s.state==='Pending'));return heading('My Work','Review tasks assigned to '+esc(state.profile)+'. Decisions use saved report revisions.')+`<section class="card">${tasks.length?`<table><thead><tr><th>Member / report</th><th>Assigned step</th><th>Due</th><th>State</th><th></th></tr></thead><tbody>${tasks.map(t=>{const r=report(t.reportId);return `<tr><td><strong>${esc(r.values.MemberName)}</strong><div class="hint">${r.values.FormKind} Â· ending ${r.values.PeriodEnd}</div></td><td>${t.steps.findIndex(s=>s.name===state.profile&&s.state==='Pending')+1} of ${t.steps.length}</td><td>Not set</td><td>${statusBadge(r)}</td><td>${button('Open review','open-review','','data-id="'+r.id+'"')}</td></tr>`;}).join('')}</tbody></table>`:'<div class="empty"><h2>No pending review tasks</h2><p>Youâ€™re caught up for this local contributor.</p></div>'}</section>`;}
function resources(){return heading('Resources','Reusable drafting tools and local reference guidance.')+`<div class="cards"><section class="card"><h2>Reporting seniors</h2><p class="muted">Reusable reporting senior details and RSCA history by evaluated paygrade.</p>${button('Manage reporting seniors','goto-seniors')}</section><section class="card"><h2>Narrative snippets</h2><p class="muted">Attributed text to insert deliberately into a pending draft.</p>${button('Browse snippets','browse-snippets')}</section><section class="card"><h2>Review routes</h2><p class="muted">Reusable sequences of named local reviewers.</p>${button('Manage templates','templates')}</section><section class="card"><h2>Reference guidance</h2><p class="muted">Form-specific trait guidance and supported draft checks.</p>${button('View guidance','guidance')}</section></div>`;}
function settings(){return heading('Settings & Help','Workspace tools, contributors and detailed diagnostics.')+`<div class="split"><section class="card"><h2>Workspace</h2><p><strong>Training command</strong><br><span class="hint">Synthetic prototype workspace</span></p>${button('Contributors','contributors')}${button('Backup / restore','backup')}</section><section class="card"><h2>Help & diagnostics</h2><p class="muted">Technical details are kept here, outside report editing.</p>${button('Operation history','operations')}${button('App limitations','limitations')}</section></div><section class="card"><h2>Prototype scenarios</h2><p class="muted">Use these controls to review empty lists and alternate states. They affect browser demo data only.</p><div class="actions">${button('Create an empty workspace','empty-demo')}${button('Reset synthetic examples','reset-demo')}</div></section>`;}
function bulk(){return heading('Bulk change','Review each changed block and its full before/after value, then apply.',button('Back to reports','goto-reports'))+`<section class="card"><div class="stepper"><${batch.length?'span':'strong'}>1 Choose</${batch.length?'span':'strong'}><${batch.length?'strong':'span'}>2 Preview</${batch.length?'strong':'span'}><span>3 Apply</span><span>4 Results</span></div>${batch.length?`<h2>Review ${batch.length} report changes</h2><p class="muted">${new Set(batch.map(b=>b.id)).size} reports, ${batch.length} changed blocks. Other saved values are preserved.</p><table><thead><tr><th>Member</th><th>Block / field</th><th>Before</th><th>After</th></tr></thead><tbody>${batch.map(b=>`<tr><td>${esc(b.member)}</td><td>${esc(fields.find(f=>f.key===b.key)?.label||b.key)}</td><td style="white-space:pre-wrap">${esc(b.before)||'<em>Not entered</em>'}</td><td style="white-space:pre-wrap">${esc(b.after)||'<em>Clear value</em>'}</td></tr>`).join('')}</tbody></table><div class="actions" style="margin-top:20px">${button('Change selection','bulk-edit')}${button('Apply reviewed changes','batch-apply','primary')}</div>`:`<p>${selected.size} selected reports</p><label>Field<select id="bulk-field">${fields.filter(f=>f.key!=='FormKind').map(f=>`<option value="${f.key}" ${f.key==='ShipStation'?'selected':''}>${esc(f.label)}</option>`).join('')}</select></label><label style="margin-top:16px">New value<textarea id="bulk-value" rows="4"></textarea></label><p class="hint">An empty value deliberately clears this field. Approved and archived reports must be reopened first.</p><div class="actions">${button('Preview changes','batch-preview','primary')}</div>`}</section>`;}
function importView(){return heading('Import a report','Choose a supported source and review exactly what will be imported.',button('Back to reports','goto-reports'))+`<section class="card"><div class="stepper"><strong>1 Choose</strong><span>2 Preview</span><span>3 Apply</span><span>4 Results</span></div><div class="split"><div class="card"><h2>NAVFIT database</h2><p class="muted">Current adapter imports the official narrative only. Other source values are retained as provenance.</p>${button('Preview synthetic NAVFIT example','import-preview','','data-source="NAVFIT"')}</div><div class="card"><h2>Interactive PDF</h2><p class="muted">Eight mapped fields from supported interactive templates. Adobe Acrobat automation is required in Access.</p>${button('Preview synthetic PDF example','import-preview','','data-source="PDF"')}</div></div><div class="alert info">This prototype does not open your files. These actions use synthetic examples to demonstrate the review flow. Full interchange and flattened-PDF import remain unavailable.</div></section>`;}
function savedAction(action){if(isDirty(report(editor.id).values,editor.values)){modal('Use which report values?', '<p>This action uses a saved revision. Your pending edits are not part of that revision.</p>',button('Cancel','cancel')+button('Use saved version','saved-use')+button('Save and continue','saved-save','primary'));dialog.dataset.savedAction=action;return;}performSavedAction(action);}
function performSavedAction(action){const r=report(editor.id);if(action==='checks'){const missing=['OfficialName','RankRate','UnitUIC'].filter(k=>!r.values[k]);modal('Limited draft checks',`<p>Checked saved revision ${r.revision}.</p><div class="alert ${missing.length?'':'info'}">${missing.length?'Needs information: '+missing.map(k=>esc(fields.find(f=>f.key===k).label)).join(', '):'No missing name, grade/rate or UIC in this synthetic example.'}</div><p class="hint">This is a design demonstration, not the Access rule engine. Full Navy policy coverage and export certification are unavailable.</p>`,button('Close','cancel'));return;}if(action==='start-review'){modal('Start a saved-revision review',`<p>Route ${esc(r.values.MemberName)}, saved revision ${r.revision}.</p><label>First reviewer<select id="first-reviewer"><option>Alex Morgan</option><option>Robin Chen</option></select></label><label style="margin-top:16px">Next reviewer<select id="next-reviewer"><option>Robin Chen</option><option>Alex Morgan</option><option>None</option></select></label><p class="hint">Starting again replaces the prototypeâ€™s active route. Production retains historical routes.</p>`,button('Cancel','cancel')+button('Start review','route-create','primary'));return;}if(action==='accept'||action==='return'){const route=state.routes.find(t=>t.reportId===r.id),step=route?.steps.find(s=>s.state==='Pending');if(!route||route.revision!==r.revision)throw Error('This review is stale. Restart it for the current saved revision.');if(step?.name!==state.profile)throw Error('Switch to the assigned local contributor to complete this step.');modal(action==='accept'?'Accept review step':'Return report with feedback','<label>Decision note<textarea id="decision-note" rows="4" required></textarea></label><p class="hint">A note is required. This decision does not establish an official signature.</p>',button('Cancel','cancel')+button(action==='accept'?'Accept step':'Return report','route-decision','primary',`data-decision="${action}"`));return;}if(action==='approve'){modal('Record local approval','<p>This locks editing after a completed current route. It is not an official signature.</p><label>Approval note<textarea id="approval-note" rows="3"></textarea></label>',button('Cancel','cancel')+button('Record local approval','approval-commit','primary'));}}
document.addEventListener('click',event=>{const errorLink=event.target.closest('[data-error-field]');if(errorLink){event.preventDefault();const f=fields.find(f=>f.key===errorLink.dataset.errorField);section=f.section;render();document.querySelector('#field-'+f.key)?.focus();return;}const a=event.target.closest('a[href^="#"]');if(a&&a.hash!=='#main'){event.preventDefault();requestNavigation(a.hash.slice(1));return;}const b=event.target.closest('[data-action]');if(!b)return;try{act(b.dataset.action,b);}catch(e){notify(e.message);}});
document.addEventListener('change',event=>{if(event.target.dataset.groupSenior){const g=state.groups[0];g.seniorId=Number(event.target.value)||null;g.rscaHistoryId=null;g.baselineExcludesGroup=false;persist();render();}if(event.target.dataset.groupRsca){const g=state.groups[0];g.rscaHistoryId=Number(event.target.value)||null;g.baselineExcludesGroup=false;persist();render();}if(event.target.dataset.rscaExcludes){state.groups[0].baselineExcludesGroup=event.target.checked;persist();render();}if(event.target.dataset.reportGroup){editor.groupId=Number(event.target.value)||null;document.querySelector('#average-summary').innerHTML=averageSummary(report(editor.id));}if(event.target.dataset.comparison){const id=Number(event.target.dataset.member),key=event.target.dataset.comparison;comparisonDraft[id]??={};comparisonDraft[id][key]=event.target.value;const g=state.groups[0];const old=document.querySelector('#group-rsca');if(old)old.outerHTML=groupRSCA(g);const v={...g.snapshot.find(s=>s.id===id).values,...comparisonDraft[id]};document.querySelector('#comparison-ita-'+id).textContent=averageDisplay(traitAverage(v));}if(event.target.dataset.select){const id=Number(event.target.dataset.select);if(event.target.checked)selected.add(id);else selected.delete(id);render();}if(event.target.dataset.filter){filters[event.target.dataset.filter]=event.target.value;render();}});
document.addEventListener('input',event=>{if(event.target.dataset.filter==='search'){filters.search=event.target.value;const pos=event.target.selectionStart;render();const input=main.querySelector('[data-filter=search]');input.focus();input.setSelectionRange(pos,pos);}});
document.querySelector('#collapse').addEventListener('click',()=>{const narrow=innerWidth<=850;document.body.classList.toggle(narrow?'nav-open':'collapsed');document.querySelector('#collapse').setAttribute('aria-expanded',String(narrow?document.body.classList.contains('nav-open'):!document.body.classList.contains('collapsed')));});
document.querySelector('#profile').addEventListener('click',()=>act('contributors'));
dialog.addEventListener('close',()=>{delete dialog.dataset.destination;delete dialog.dataset.savedAction;});
window.addEventListener('beforeunload',event=>{if(page==='senior-editor'&&(seniorIsDirty()||Object.keys(seniorBaseline).length)){event.preventDefault();event.returnValue='';return;}if(editor&&isDirty(report(editor.id).values,editor.values)){checkpoint();event.preventDefault();event.returnValue='';}});
function checkpoint(){if(editor&&isDirty(report(editor.id).values,editor.values)){state.recovery={reportId:editor.id,values:clone(editor.values)};persist();const c=document.querySelector('#checkpoint-status');if(c)c.textContent='Recovery checkpoint at '+new Date().toLocaleTimeString()+' Â· Not a saved revision';}}
setInterval(checkpoint,30000);
function groups(){return heading('Summary groups','Choose a group to manage its members, shared report values and comparison.',button('New group','new-group','primary'))+`<section class="card">${state.groups.length?`<table><thead><tr><th>Summary group</th><th>Report type</th><th>Paygrade</th><th>Members</th><th>Trait average</th><th></th></tr></thead><tbody>${state.groups.map(g=>`<tr><td><button class="link" data-action="group-open" data-id="${g.id}">${esc(g.title)}</button></td><td>${g.kind}</td><td>${g.grade}</td><td>${g.members.length}</td><td>${averageDisplay(groupAverage(state,g.id))}</td><td>${button('Open group','group-open','','data-id="'+g.id+'"')}</td></tr>`).join('')}</tbody></table>`:'<div class="empty"><h2>No summary groups yet</h2><p>Create a group and explicitly select its members.</p></div>'}</section>`;}
function averageDisplay(a){return a.value===null?(a.nob?'NOB':'â€”'):a.value.toFixed(2)+(a.partial?' Â· partial':'');}
function averageSummary(r){const groups=state.groups.filter(g=>g.members.includes(r.id)),group=groups.find(g=>g.id===editor.groupId),a=group?groupAverage(state,group.id):{value:null};return `<div class="averages"><span><strong>ITA</strong> ${averageDisplay(traitAverage(editor.values))}<small>Pending marks</small></span><span><strong>Saved ITA</strong> ${averageDisplay(traitAverage(r.values))}<small>Revision ${r.revision}</small></span><span><strong>Summary Group Average</strong> ${averageDisplay(a)}<small>${group?esc(group.title)+' Â· saved values':groups.length?'Choose a group':'Not assigned to a group'}</small></span>${groups.length>1?`<label>Group context<select data-report-group="true"><option value="">Choose a group</option>${groups.map(g=>`<option value="${g.id}" ${g.id===editor.groupId?'selected':''}>${esc(g.title)}</option>`).join('')}</select></label>`:''}</div>`;}
function memberFields(fs,locked,values=editor.values){
 const sets=[['Duty/Competitive Status',f=>f.key.startsWith('Component')],['Occasion for Report',f=>f.key.startsWith('Occasion')],['Period of Report',f=>['PeriodStart','PeriodEnd'].includes(f.key)],['Type of Report',f=>['ReportRegular','ReportConcurrent','ReportOperationalCommander'].includes(f.key)]];
 const rendered=new Set();let html='';
 for(const f of fs){if(rendered.has(f.key))continue;const set=sets.find(([,match])=>match(f));if(set){const members=fs.filter(set[1]);members.forEach(m=>rendered.add(m.key));html+=`<fieldset class="field wide block-set"><legend>${set[0]}</legend><div class="field-grid">${members.map(m=>fieldHTML(m,locked,values)).join('')}</div></fieldset>`;}else{rendered.add(f.key);html+=fieldHTML(f,locked,values);}}
 return html;
}
const sharedKeys=new Set(['CommandEmployment','UnitUIC','ShipStation','PromotionStatus','PeriodStart','PeriodEnd','DateReported','OccasionPeriodic','OccasionDetachment','OccasionFrocking','OccasionSpecial','ReportRegular','ReportConcurrent','ReportOperationalCommander','ObservationStatus','ComponentActive','ComponentTAR','ComponentInactive','ComponentATADSW','BilletSubcategory','ReadinessSummary','ReadinessDetail','ReadinessDate','ReportingSeniorName','ReportingSeniorGrade','ReportingSeniorDesignator','ReportingSeniorTitle','ReportingSeniorUIC','ReportingSeniorSSN','ReportingSeniorAddress1','ReportingSeniorAddress2','ReportingSeniorCity','ReportingSeniorState','ReportingSeniorZip','ReportingSeniorPhone','ReportingSeniorDSN','PrimaryDuty','DutyDescription','ReportingSeniorLastName','ReportingSeniorFirstInitial','ReportingSeniorMiddleInitial']);
function beginBulkEditor(ids){comparisonBatchGuard=null;if(!ids.length)throw Error('Add group members first.');selected=new Set(ids);const values=ids.map(id=>report(id).values);bulkValues={FormKind:values[0].FormKind};for(const f of fields)bulkValues[f.key]=values.every(v=>v[f.key]===values[0][f.key])?values[0][f.key]:'';bulkValues.FormKind=values[0].FormKind;bulkTouched=new Set();bulkSection=0;batch=[];page='bulk-editor';render();}
function bulkEditor(){const fs=fields.filter(f=>sharedKeys.has(f.key)&&f.section===bulkSection&&!f.legacyHidden).sort((a,b)=>(parseInt(a.block)||999)-(parseInt(b.block)||999));return heading('Shared report blocks','Edit the same sections used in an individual report. Only changed entries will be applied to '+selected.size+' selected members.',button('Back to group','goto-group-detail'))+`<div class="stepper"><strong>1 Edit blocks</strong><span>2 Preview</span><span>3 Apply</span><span>4 Results</span></div><div class="editor-layout"><nav class="section-nav" aria-label="Shared report sections">${[0,2,6].map(i=>`<button data-action="bulk-section" data-section="${i}" ${bulkSection===i?'aria-current="page"':''}>${sectionNames[i]}<small>${sectionRange(i,bulkValues.FormKind)}</small></button>`).join('')}</nav><section class="card"><h2>${sectionNames[bulkSection]}</h2><div class="alert info">Unchanged blocks are preserved. Mixed starting values appear blank. Clearing an entry deliberately stages a clear operation. All changes are shown before Apply.</div><div class="field-grid">${bulkSection===0?memberFields(fs,false,bulkValues):fs.map(f=>fieldHTML(f,false,bulkValues)).join('')}</div></section></div><div class="save-bar"><span class="status">${bulkTouched.size} changed entries staged Â· No report revisions saved yet</span>${button('Preview changes','section-preview','primary')}</div>`;}
function bindBulkFields(){main.querySelectorAll('[data-field]').forEach(input=>{if(input.type==='checkbox')input.indeterminate=!bulkValues[input.dataset.field];input.addEventListener('input',()=>{bulkValues[input.dataset.field]=input.type==='checkbox'?(input.dataset.field==='ObservationStatus'?(input.checked?'NOB':'Observed'):(input.checked?'Yes':'No')):(fields.find(f=>f.key===input.dataset.field)?.digits===9&&/^\d{3}-\d{2}-\d{4}$/.test(input.value)?input.value.replaceAll('-',''):input.value);bulkTouched.add(input.dataset.field);main.querySelector('.save-bar .status').textContent=bulkTouched.size+' changed entries staged Â· No report revisions saved yet';});});}
function comparisonContent(g){
 if(!g.members.length)return '<div class="empty"><h3>No group members yet</h3><p>Add members to compare their traits.</p></div>';
 if(!g.snapshot){captureComparison(state,g);comparisonDraft={};persist();}
 const stale=g.snapshot&&(g.members.length!==g.snapshot.length||g.snapshot.some(s=>!g.members.includes(s.id)||report(s.id)?.revision!==s.revision));

 const traitKeys=fields.filter(f=>f.key.startsWith('Trait')),locked=stale;
 return `<div class="actions" style="margin-bottom:16px">${button('Refresh comparison','comparison-refresh')}${button('Preview proposed changes','comparison-preview','primary',locked?'disabled title="Refresh the comparison first"':'')}${button('Discard proposed edits','comparison-reset')}</div>${stale?'<div class="alert">Saved group values changed. Refresh the comparison before applying proposals.</div>':'<p class="hint">Edit trait marks directly below. These are proposed values; saved reports change only after Preview and Apply. Approved rows require reopening.</p>'}<div class="table-wrap"><table class="comparison-grid"><thead><tr><th>Member</th>${traitKeys.map(f=>{const t=traits.find(t=>t.FormKind===g.kind&&'Trait'+t.Block===f.key);return `<th title="${esc(t?.Title.replace(/\s+/g,' ')||f.label)}">${f.block}</th>`;}).join('')}<th>ITA</th><th>Promotion recommendation</th><th>Order</th></tr></thead><tbody>${g.snapshot.map((s,i)=>{const v={...s.values,...comparisonDraft[s.id]},rowLocked=locked||report(s.id).state==='Approved'||report(s.id).archived;return `<tr><td><strong>${esc(v.MemberName)}</strong><div class="hint">${esc(v.RankRate)} Â· revision ${s.revision}${rowLocked?' Â· locked':''}</div></td>${traitKeys.map(f=>`<td><select data-comparison="${f.key}" data-member="${s.id}" aria-label="${esc(v.MemberName)} Â· block ${f.block} ${esc(traits.find(t=>t.FormKind===g.kind&&'Trait'+t.Block===f.key)?.Title||f.label)}" ${rowLocked?'disabled':''}>${f.options.map(o=>`<option value="${o}" ${v[f.key]===o?'selected':''}>${o||'â€”'}</option>`).join('')}</select></td>`).join('')}<td id="comparison-ita-${s.id}" class="numeric">${averageDisplay(traitAverage(v))}</td><td><select data-comparison="PromotionRecommendation" data-member="${s.id}" aria-label="${esc(v.MemberName)} promotion recommendation" ${rowLocked?'disabled':''}>${fields.find(f=>f.key==='PromotionRecommendation').options.map(o=>`<option value="${o}" ${v.PromotionRecommendation===o?'selected':''}>${o||'Not entered'}</option>`).join('')}</select></td><td>${button('â†‘','order-up','','aria-label="Move '+esc(v.MemberName)+' up" data-index="'+i+'" '+(i===0?'disabled':''))}</td></tr>`;}).join('')}</tbody></table></div><p class="hint">Trait columns are numbered 33â€“39; hover a heading for its form-specific name. ITA reflects proposed marks. Manual order is presentation only.</p>`;
}
function comparisonStamp(g){return JSON.stringify(g.members.map(id=>[id,report(id)?.revision,report(id)?.archived]).sort((a,b)=>a[0]-b[0]));}
function previewComparison(){const g=state.groups[0];if(!g.snapshot||g.members.length!==g.snapshot.length||g.snapshot.some(s=>!g.members.includes(s.id)||report(s.id)?.revision!==s.revision))throw Error('The group comparison is stale. Refresh the comparison.');batch=Object.entries(comparisonDraft).flatMap(([id,changes])=>previewChanges(state,[Number(id)],changes));if(!batch.length)throw Error('Edit a trait mark or recommendation in the comparison grid first.');comparisonBatchGuard={groupId:g.id,stamp:comparisonStamp(g)};page='bulk';render();}
function seniorSelector(){return `<div class="actions"><label>Reuse reporting senior details<select id="report-senior"><option value="">Choose a record</option>${state.reportingSeniors.map(s=>`<option value="${s.id}">${esc(s.title)}</option>`).join('')}</select></label>${button('Use in pending draft','senior-use')}${button('Manage records','goto-seniors')}</div><p class="hint">Using a record replaces the reporting senior fields in this pending draft. Save draft commits the change. Stored full names remain independent of name parts.</p>`;}
function seniorList(){return heading('Reporting seniors','Reusable block details and historical RSCA by the paygrade evaluated.',button('New reporting senior','senior-new','primary')+button('Back to resources','goto-resources'))+`<section class="card">${state.reportingSeniors.length?`<table><thead><tr><th>Record</th><th>Name</th><th>Grade</th><th>UIC</th><th>RSCA entries</th><th></th></tr></thead><tbody>${state.reportingSeniors.map(s=>`<tr><td>${esc(s.title)}</td><td>${esc(s.values.ReportingSeniorName)}</td><td>${esc(s.values.ReportingSeniorGrade)}</td><td>${esc(s.values.ReportingSeniorUIC)}</td><td>${s.history.length}</td><td>${button('Open','senior-open','','data-id="'+s.id+'"')}</td></tr>`).join('')}</tbody></table>`:'<div class="empty"><h2>No reporting seniors yet</h2><p>Add their details once, then deliberately reuse them in reports and groups.</p></div>'}</section>`;}
function seniorInput(key,label,value,type='text'){return `<label>${esc(label)}<input data-senior-field="${key}" type="${type}" value="${esc(value||'')}" aria-invalid="${Boolean(seniorErrors[key])}">${seniorErrors[key]?`<span class="field-error">${esc(seniorErrors[key])}</span>`:''}</label>`;}
function seniorEditor(){const s=seniorDraft;return heading(s.id?'Reporting senior record':'New reporting senior','Changes to this record do not automatically change saved reports.',button('Back to reporting seniors','goto-seniors'))+`<section class="card">${Object.keys(seniorErrors).length?'<div class="alert error" role="alert">Correct the highlighted entries. Pending values are retained.</div>':''}${seniorInput('title','Record name',s.title)}<h2 style="margin-top:20px">Reporting senior blocks</h2><div class="field-grid">${reportingSeniorKeys.map(key=>{const f=fields.find(f=>f.key===key);return seniorInput(key,(f.block?f.block+'. ':'')+f.label,s.values[key]);}).join('')}</div><div class="actions" style="margin-top:20px">${button('Save record','senior-save','primary')}<span id="senior-dirty" class="hint">${seniorIsDirty()?'Unsaved changes':'Saved record'}</span></div><h2 style="margin-top:24px">Historical RSCA</h2><p class="hint">Record totals before the group being prepared. Trait count means graded traits, not reports. Exact total trait sum is optional; without it PSG RSCA is an estimate based on the rounded RSCA.</p><div class="field-grid"><label>Evaluated paygrade<select id="rsca-grade">${paygrades.map(g=>`<option>${g}</option>`).join('')}</select></label><label>As-of date<input type="date" id="rsca-asof"></label><label>RSCA<input id="rsca-average" type="number" min="1" max="5" step="0.01"></label><label>Previous graded trait count<input id="rsca-count" type="number" min="0" step="1"></label><label>Exact total trait sum (optional)<input id="rsca-sum" type="number" min="0" step="1"></label><label>Source / note<input id="rsca-note" maxlength="255" placeholder="For example, BOL totals as of this date"></label></div><div class="actions" style="margin-top:16px">${button('Save record and add RSCA baseline','senior-history-save')}</div><div id="rsca-errors" class="field-error" role="alert"></div><table style="margin-top:20px"><thead><tr><th>Paygrade</th><th>As of</th><th>RSCA</th><th>Trait count</th><th>Exact trait sum</th><th>Source / note</th></tr></thead><tbody>${s.history.map(h=>`<tr><td>${h.grade}</td><td>${h.asOf}</td><td>${h.rsca||'No prior traits'}</td><td>${h.traitCount}</td><td>${h.traitSum===''?'Not entered':h.traitSum}</td><td>${esc(h.note)}</td></tr>`).join('')}</tbody></table></section>`;}
function seniorIsDirty(){if(!seniorDraft)return false;const old=state.reportingSeniors.find(s=>s.id===seniorDraft.id);return !old||JSON.stringify(old)!==JSON.stringify(seniorDraft);}
function readSeniorBaseline(){return {grade:document.querySelector('#rsca-grade').value,asOf:document.querySelector('#rsca-asof').value,rsca:document.querySelector('#rsca-average').value,traitCount:document.querySelector('#rsca-count').value,traitSum:document.querySelector('#rsca-sum').value,note:document.querySelector('#rsca-note').value};}
function bindSeniorFields(){for(const [key,id] of Object.entries({grade:'rsca-grade',asOf:'rsca-asof',rsca:'rsca-average',traitCount:'rsca-count',traitSum:'rsca-sum',note:'rsca-note'})){const input=document.querySelector('#'+id);if(key in seniorBaseline)input.value=seniorBaseline[key];input.addEventListener('input',()=>{seniorBaseline=readSeniorBaseline();nodeSeniorDirty();});}main.querySelectorAll('[data-senior-field]').forEach(input=>input.addEventListener('input',()=>{const key=input.dataset.seniorField,value=input.value;if(key==='title')seniorDraft.title=value;else seniorDraft.values[key]=key==='ReportingSeniorSSN'?value.replaceAll('-',''):value;nodeSeniorDirty();}));}
function nodeSeniorDirty(){document.querySelector('#senior-dirty').textContent='Unsaved changes';}
function saveSenior(history){seniorErrors=validateSenior(seniorDraft);if(Object.keys(seniorErrors).length){render();return false;}const next=clone(seniorDraft);if(history)next.history.unshift({...history,id:Math.max(0,...next.history.map(h=>h.id))+1});if(!next.id)next.id=Math.max(0,...state.reportingSeniors.map(s=>s.id))+1;const index=state.reportingSeniors.findIndex(s=>s.id===next.id);if(index<0)state.reportingSeniors.push(next);else state.reportingSeniors[index]=next;seniorDraft=clone(next);if(history)seniorBaseline={};persist();render();notify('Reporting senior record saved. Saved report values were not changed.');return true;}
function groupRSCA(g){const senior=state.reportingSeniors.find(s=>s.id===g.seniorId),histories=(senior?.history||[]).filter(h=>h.grade===g.grade),a=psgRSCA(state,g.id),pending=groupTab==='Comparison'&&Object.keys(comparisonDraft).length?psgRSCA(state,g.id,comparisonDraft):null;return `<section id="group-rsca" class="card" style="margin-bottom:20px"><h3>Reporting senior &amp; PSG RSCA</h3><div class="field-grid"><label>Reporting senior<select data-group-senior="true"><option value="">Choose a reporting senior</option>${state.reportingSeniors.map(s=>`<option value="${s.id}" ${s.id===g.seniorId?'selected':''}>${esc(s.title)}</option>`).join('')}</select></label><label>${g.grade} historical baseline<select data-group-rsca="true"><option value="">Choose a baseline</option>${histories.map(h=>`<option value="${h.id}" ${h.id===g.rscaHistoryId?'selected':''}>${h.asOf} - RSCA ${h.rsca||'none'}, ${h.traitCount} traits</option>`).join('')}</select></label></div><label class="check-row"><input type="checkbox" data-rsca-excludes="true" ${g.baselineExcludesGroup?'checked':''}>Historical totals exclude all reports in this summary group.</label><div class="actions">${button('Manage reporting seniors','goto-seniors')}${button('Preview applying senior details to members','group-senior-apply','',senior?'':'disabled')}</div><p><strong>PSG RSCA (saved group): ${a.value===null?'Unavailable':a.value.toFixed(2)+(a.estimated?' - estimate':'')}</strong></p>${a.value===null?`<p class="hint">${esc(a.reason)}</p>`:`<p class="hint">(${a.previousSum.toFixed(2)} historical trait sum + ${a.groupSum} group trait sum) / (${a.previousCount} historical traits + ${a.groupCount} group traits). ${a.partial?'Some report traits are blank or NOB; only numeric traits are included.':''} ${a.estimated?'Enter the exact historical trait sum for a calculation from exact totals.':''}</p>`}${pending?`<p>Proposed PSG RSCA: ${pending.value===null?esc(pending.reason):pending.value.toFixed(2)+(pending.estimated?' - estimate':'')} (pending comparison marks)</p>`:''}<p class="hint">This calculation does not update the historical totals or insert text into report comments.</p></section>`;}
